insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 1, 'What does the Professional tier add to the Associate tier''s earth model?', '["A fault polygon that cuts the model into blocks and reports a per-block census for accounting.", "The depth-down clamp and its counts of 0, 0 and 180.", "Per-block property population of the model by trend fitting and simple kriging.", "Wells: trajectories, landed picks, and the tie table that compares surfaces to rock."]'::jsonb, 3, 'The Associate tier built the container with no wells in it; this tier ties four wells to it. Faults and population belong to the Expert tier, and the clamp is Associate work.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 2, 'Which well in the golden set carries a real deviation?', '["W4, because its kelly bushing is 28 m above sea level.", "W3, the deepest well in measured depth.", "W2, which builds to 45 degrees heading due east.", "W1, whose single survey station sits at 2000 m of measured depth."]'::jsonb, 2, 'W1, W3 and W4 are vertical; their single zero-inclination station says so. W2 holds vertical to 1200 m MD, builds to 45 degrees by 1500, and holds that angle east.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 3, 'A pick is recorded at 1595 m MD in W1 (KB 25 m, vertical). What is its TVDSS?', '["It cannot be computed without the survey stations.", "1570 m, from MD minus KB.", "1595 m, since a vertical well needs no conversion at all.", "1620 m, adding the bushing height to the measured depth."]'::jsonb, 1, 'For a vertical hole TVDSS = MD minus KB = 1595 - 25 = 1570. Adding KB is the classic sign error. The survey is what SAYS the well is vertical, but the arithmetic then needs only the subtraction.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 4, 'What does a TVDSS of minus 30 at the start of W2''s path mean?', '["The trajectory is broken: depths must start at zero at the bushing and increase monotonically.", "The kelly bushing sits 30 m above sea level, so depth below datum is negative there.", "The sea floor at W2 is 30 m below the datum.", "The first survey station was recorded 30 m too shallow."]'::jsonb, 1, 'TVDSS = TVD - KB, and at MD 0 the TVD is 0, giving minus KB. The bushing genuinely stands above the datum, so a negative depth below datum is correct, not a bug.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 5, 'Why do the framework surfaces force every tie to be computed in TVDSS?', '["Because the surfaces are stored in metres below sea level.", "Because TVDSS removes the effect of the well''s azimuth and inclination from every comparison.", "Because wireline tools record TVDSS directly.", "Because measured depth cannot exceed 2000 m in the fixture."]'::jsonb, 0, 'The model''s z datum is TVDSS (metres below MSL, positive down). Picks arrive in MD, so they must be converted before any subtraction against a surface makes sense. Tools record MD, not TVDSS.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 6, 'Two wells pick the same formation at the same MD but have different KB heights. What follows?', '["Their residuals against the formation''s surface must come out exactly equal.", "One of the two picks must be miscorrelated.", "They found the formation at different depths below sea level.", "They found the formation at exactly the same depth below sea level."]'::jsonb, 2, 'TVDSS subtracts KB, so equal MDs with different bushings land at different depths below datum. Nothing about correlation or residuals follows from the MDs alone.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 7, 'How much of zone B does every golden well log in measured depth?', '["120 m, the largest zone interval carried by any well in the set.", "30 m, except W2 which logs 60 m of hole through it.", "27 m at W1 and zero at the eastern wells, matching the clamped model.", "45 m in each of the four wells."]'::jsonb, 1, 'W1, W3 and W4 log zone B over 30 m of MD; W2''s 60 m of hole at 45 degrees crosses about 42 m of rock. The 27 and 0 are the MODEL''s zone B thicknesses, and 120 m is W2''s zone A interval.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 8, 'The worst residual in the set was already quoted by the Associate tier. What does this tier add about it?', '["The mechanism: how much is trajectory and how much is the model''s pinched zone B.", "A corrected, smaller value recomputed after the clamp is turned off for BaseB.", "Proof that the deviated well''s survey was recorded wrongly.", "Nothing; the number is simply re-derived to more decimals."]'::jsonb, 0, 'The 45.028 m headline is forward-quoted; the tier''s work is the decomposition, which shows vertical wells carry 37 and 36 m BaseB residuals too, so deviation is not the whole story.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 9, 'Which statement about the four wellheads is correct?', '["W3 and W4 are the closest pair of wellheads.", "All four wellheads lie on the same north-south line.", "W2''s wellhead lies east of W4''s.", "W1 and W2 are the closest pair of wellheads."]'::jsonb, 3, 'W1 (1100, 2100) to W2 (1400, 2200) is about 316 m; W3 (1900, 2700) to W4 (2050, 2150) is about 570 m. W2''s head at x 1400 is far west of W4''s at 2050.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 10, 'What is the panel''s exposed assumption in the tie explorer?', '["The choice of which framework surface each pick''s name ties against in the table.", "The grid spacing of the model frame.", "The trajectory: you can replace the survey with a straight vertical hole.", "The kelly bushing height, adjustable per well from the panel''s controls."]'::jsonb, 2, 'The panel exposes the assumption every quick-look workflow makes silently: that holes are plumb lines. KB, top-to-surface binding and the frame are fixture facts, not panel controls.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 11, 'In the tie explorer''s section drawing, what is the dashed bar at each pick?', '["The distance from the landed pick to the nearest node of the model frame.", "The residual, drawn at true scale from the pick to its surface.", "The uncertainty range of the surface at that location, one standard deviation each way.", "The thickness of the zone below the pick."]'::jsonb, 1, 'The bar connects the landed pick''s TVDSS to the surface''s depth there; its length IS the residual. It is not an uncertainty, which the tie table does not measure.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 12, 'Why does the section for W2 show the TopB and BaseB curves merging east of the well?', '["Because the clamp pinched zone B to zero thickness there.", "Because the two surfaces were accidentally swapped in the fixture.", "Because the section is drawn at the wrong y coordinate.", "Because bilinear sampling smooths the two surfaces together."]'::jsonb, 0, 'The Associate tier''s clamp fixed 180 BaseB nodes onto TopB where zone B pinches out; where that happens the two clamped surfaces are one line. Sampling does not merge distinct surfaces.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 13, 'Zone A runs from which pick to which pick in every golden well?', '["From the TopA pick to the BaseB pick.", "From the TopB pick to the BaseB pick.", "From the kelly bushing to the TopA pick.", "From the TopA pick to the TopB pick."]'::jsonb, 3, 'Zone A is bounded by TopA and TopB; zone B runs from TopB to BaseB. The intervals follow the picks by construction.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 14, 'Which capstone field belongs to the NEXT tier''s story rather than the tie table itself?', '["The largest absolute residual in the well set.", "W2''s TVDSS at its TopA pick.", "The x coordinate of W2''s zone A control point.", "W1''s BaseB residual."]'::jsonb, 2, 'The control point is where W2''s zone information will stand when the Expert tier populates properties per fault block; the other three fields are tie-table quantities.'),
  ('earthmodel', 'intermediate', 'module', 'm01-a-well-is-not-a-vertical-line', 15, 'W3 has KB 20 m and picked TopB at 1625 m MD; the surface there reads 1598 m. What is the residual?', '["Plus 47 m, obtained by forgetting to subtract the kelly bushing height.", "Plus 7 m: the well found the formation deeper than the surface.", "Minus 7 m: the well found the formation shallower than the surface.", "Plus 27 m, the model''s zone B thickness at W1."]'::jsonb, 1, 'TVDSS = 1625 - 20 = 1605; residual = 1605 - 1598 = +7, and positive means the pick sits deeper than the surface. Forgetting KB would give 1625 - 1598 = 27, which is also a real number in the course in a different role.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 1, 'What three numbers does a survey station record?', '["Measured depth, dogleg and ratio factor.", "Inclination, azimuth and kelly bushing height.", "Measured depth, inclination and azimuth.", "Easting, northing and true vertical depth."]'::jsonb, 2, 'A station is MD plus the hole''s attitude: angle from vertical and compass direction. Positions are computed FROM stations; dogleg and ratio factor are derived per segment.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 2, 'What does the engine do about the hole above W2''s first station at 1200 m MD?', '["It clamps every position above 1200 m to the station at 1200.", "It prepends an implied vertical station at MD 0, so the top section is a vertical line.", "It refuses to build the trajectory until a station at the surface is supplied by the user.", "It extrapolates the build backwards, curving the shallow hole gently west of the rig."]'::jsonb, 1, 'Every trajectory starts with an implied MD 0 station at zero inclination, a documented convention. Clamping applies BEYOND the last station, not above the first.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 3, 'A survey contains a station whose MD repeats the previous station''s. What happens?', '["The station is skipped, because a zero-length segment cannot carry geometry.", "The engine throws a zero-length segment error and the trajectory fails to build.", "The two stations are averaged into one.", "The trajectory doubles back on itself at that measured depth and continues upward."]'::jsonb, 0, 'Stations with non-increasing MD are dropped; a repeated MD would otherwise divide by a zero segment length. The golden fixtures are clean, so the branch is a safety net.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 4, 'Why does the position increment from 1200 to 1500 m MD use the attitudes at BOTH stations?', '["Because averaging MDs cancels the survey tool''s calibration error.", "Because the azimuth at 1200 m alone determines the whole segment''s direction of travel.", "Because the engine needs a second station to estimate the kelly bushing height above datum.", "Because minimum curvature fits an arc that honours the measured attitude at each end."]'::jsonb, 3, 'The method''s defining move is one circular arc matching both end attitudes. One-ended methods like the tangential method mislocate the build endpoint by roughly 100 m here.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 5, 'What is the dogleg of W2''s build segment, and why does the 90 degree azimuth change cost nothing?', '["135 degrees, the sum of the inclination and azimuth changes.", "45 degrees; the engine ignores azimuth for all build segments.", "45 degrees; sin of the first inclination is zero, so the azimuth term vanishes.", "90 degrees, the full azimuth change between the stations."]'::jsonb, 2, 'The spherical cosine rule''s azimuth term is scaled by sin I1 sin I2; with I1 = 0 it vanishes, leaving the 45 degree inclination change. A vertical hole has no direction to change. Azimuth is not ignored in general.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 6, 'Compute the ratio factor for a 45 degree dogleg.', '["Exactly 1, because a 45 degree dogleg is below the engine''s straightness threshold.", "1.054786175158099, from (2 divided by the dogleg) times tan of half the dogleg.", "0.900316316157106, the arc length of the segment divided by its straight chord.", "1.110720734539592, pi over four times sqrt 2."]'::jsonb, 1, 'RF = (2/b) tan(b/2) with b = pi/4 gives (8/pi)(sqrt 2 - 1) = 1.054786175158099. The straightness shortcut applies only below 0.0001 radians.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 7, 'Over the 300 m build, how far east and how far down does W2 travel?', '["111.87696857341697 m east and 270.09489484713185 m down.", "212.13 m east and 212.13 m down.", "150 m east and 300 m down.", "111.87696857341697 m east and exactly 300.00 m down, the full segment length."]'::jsonb, 0, 'The averaged direction vectors scaled by 150 times RF give 111.877 east, 270.095 down. The 212.13 pair is the tangential method''s wrong answer, and 300 m down would mean turning cost no vertical progress.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 8, 'Why is the build''s vertical progress 270.09 m rather than 300 m?', '["The kelly bushing height is subtracted from the segment length.", "29.9 m of the hole was travelling north during the build.", "Rounding in the ratio factor loses about 10 percent.", "Turning spends hole length."]'::jsonb, 3, 'The 29.9 m gap is the geometric price of the turn, not rounding, and nothing moves north in a due-east build. KB affects TVDSS, not segment geometry.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 9, 'In the hold at 45 degrees, what does each 100 m of measured depth buy?', '["50 m east and 86.6 m of vertical depth, the thirty degree split.", "70.71 m east and the full 100 m of vertical depth at the same time.", "70.71067811865474 m east and the same amount of vertical depth.", "100 m of vertical depth and no easting."]'::jsonb, 2, 'At 45 degrees, sin and cos are equal at 0.7071, so east and down advance together. The 50/86.6 split belongs to a 30 degree hold, and no segment can advance vertically by its full measured length while also moving east.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 10, 'How does the engine locate a pick at 1580 m MD, between the stations at 1500 and 1900?', '["Cubic spline interpolation fitted through all four of the survey stations.", "Linear interpolation in measured depth between the two stations'' positions.", "By re-solving the minimum curvature arc equations at the pick''s exact measured depth.", "By snapping the pick to the nearer station at 1500 m."]'::jsonb, 1, 'Between stations, positions interpolate linearly in MD, a documented convention. Within a hold this is exact, because the true path IS straight there.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 11, 'Why are W2''s landed pick positions exact to the last digit despite the interpolation convention?', '["All three picks lie in the hold, where the true path is straight.", "The engine''s interpolation is exact everywhere by construction, whatever the segment shape.", "The picks were snapped to survey stations before landing.", "The build segment''s arc is short enough to ignore."]'::jsonb, 0, 'Linear-in-MD interpolation cuts corners inside an ARC, but W2''s picks at 1580, 1700 and 1760 all sit past the build''s end at 1500. The fixture separates arc subtleties from interpolation on purpose.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 12, 'What does the engine report for a position request at 2100 m MD, beyond W2''s last station?', '["A position extended onward along the hold''s 45 degree line indefinitely.", "Null, and the request is silently dropped from the returned results.", "An exception that aborts the trajectory build.", "The last station''s position: it clamps rather than extrapolates."]'::jsonb, 3, 'Beyond the surveyed range the engine returns the last station''s position. Refusing to extrapolate is a documented choice; extending the hold would be asserting attitude data that does not exist.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 13, 'Station 1500 lands at x 1511.876968573417. Where does station 1900 land?', '["x 1794.719681048036, adding the full 300 m of measured hold length as easting.", "x 1900, matching its measured depth.", "x 1794.719681048036, adding 282.84271247461896 m of easting in the hold.", "x 1683.753937146834, adding a second build increment''s worth of easting."]'::jsonb, 2, 'The 400 m hold contributes 400/sqrt 2 = 282.84 m east. Doubling the build increment or equating x with MD are both real mistakes the numbers punish.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 14, 'W2''s TVDSS at 1900 m MD is 1722.9376073217509. What was its TVDSS at 1500 m MD?', '["1170, the TVDSS at the top of the build.", "1440.0948948471319, which is 282.84271247461896 m shallower.", "1422.9376073217509, exactly 300 m shallower than the deepest station.", "1470.0948948471319, the true vertical depth stored at that station."]'::jsonb, 1, 'The hold advances 282.84 m vertically over its 400 m of hole. 1470.09 is the TVD (before KB subtraction) and 1170 is the TVDSS at station 1200, one segment higher.'),
  ('earthmodel', 'intermediate', 'module', 'm02-minimum-curvature', 15, 'How many metres of vertical rock does W2 cross between its TopA and BaseB picks, using 180 m of hole?', '["127.27922061357856 m, which is 90 times the square root of 2.", "180 m, since rock thickness always equals the measured interval along the hole.", "84.8528137423857 m, the zone A transit alone.", "106.05734204436567 m, the vertical assumption''s depth error at BaseB."]'::jsonb, 0, '1623.9426579556343 minus 1496.6634373420557 = 127.279 m = 180 cos 45. The 84.85 is only TopA to TopB, and 106.06 is the vertical-assumption error at BaseB, a different quantity from a later module.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 1, 'What exactly does a formation top pick assert?', '["That the zone below the pick has a specific thickness in true vertical depth.", "That along this hole, at this measured depth, the formation changed.", "That the formation lies at exactly this depth below the sea level datum.", "That the framework surface passes through this point."]'::jsonb, 1, 'A pick is an interpretation event on the logs, recorded in MD along the hole. Its position in space is derived from the trajectory, and it claims nothing about surfaces or zones.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 2, 'Move a well''s trajectory and what happens to its picks?', '["Every pick''s 3D position moves, though nothing about the logs changed.", "The picks'' measured depths all shift along the hole by the same amount.", "Nothing: picks are anchored in world coordinates once they have been landed.", "The picks are re-correlated to new log breaks."]'::jsonb, 0, 'A pick''s location is derived: MD along a path. Change the path, and the same MD lands somewhere else. The MDs themselves and the logs are untouched.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 3, 'How does the engine bind a pick to a framework surface?', '["By depth order: the shallowest pick ties against the shallowest surface.", "By fuzzy matching of the name against the surface list.", "Every pick is tied against all three surfaces and the smallest residual wins.", "By the pick''s NAME, through an explicit index; unmatched names are skipped."]'::jsonb, 3, 'TopA maps to surface 0, TopB to 1, BaseB to 2, by name. A misspelled pick produces NO tie row rather than a guessed one, which is why a well with fewer rows than picks is a QC signal.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 4, 'W2 and W3 both pick TopA at 1580 m MD. Why do their landed depths differ by 63 m?', '["Because the TopA surface is 63 m deeper at W3 than at W2.", "They do not differ; equal MDs land at equal depths.", "Different trajectories and bushings.", "Because W3''s pick is miscorrelated by 63 m."]'::jsonb, 2, 'W3 lands at 1560 (1580 - 20); W2''s deviated path puts 1580 m of hole at only 1496.66 m TVDSS. Same cable depth, different rock: the pair is the fixture''s cleanest MD-versus-position demonstration.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 5, 'What does it mean that a deviated well samples the model ''along a line, not at a point''?', '["Its residuals are averaged along the trajectory.", "Its picks land at different x positions, each reading the surface elsewhere.", "Its logs are recorded continuously rather than at stations.", "The engine averages the surface along the whole path before tying each pick."]'::jsonb, 1, 'W2''s three picks land 168, 253 and 296 m east of the wellhead: three different places on the map. Nothing is averaged; each tie reads its own location.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 6, 'How is a surface value obtained at a landing that is not on a grid node?', '["Bilinear blending of the four surrounding nodes; null if any is dead.", "Nearest-node lookup within half a cell.", "Inverse distance weighting computed over every live node of the frame.", "Linear interpolation along the well path between the two nearest picks."]'::jsonb, 0, 'sampleAtXY converts to fractional grid coordinates and blends the four corners; a compromised neighbourhood returns null rather than degrading to three corners.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 7, 'Why did the three vertical wells'' surface reads come out as stored grid values with no blending?', '["Vertical wells always bypass the sampling machinery.", "The engine rounds every landing to the nearest node before sampling any surface.", "Their surfaces are constant near the wellheads.", "Their wellheads happen to sit exactly on frame nodes."]'::jsonb, 3, 'W1 (1100, 2100), W3 (1900, 2700) and W4 (2050, 2150) are all node positions of the 50 m frame from (1000, 2000), so the bilinear weights collapse onto one node. That is fixture kindness, not an engine rule.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 8, 'W2''s TopA landing has row exactly 4 and column 11.368910221366814. What does the sample reduce to?', '["A full four-node bilinear blend across the two neighbouring rows.", "Null, because the column is not an integer.", "A linear blend of the two nodes at columns 11 and 12 on that row.", "The node at column 11 alone, since the fraction sits below one half."]'::jsonb, 2, 'With the row exact, the y weights collapse and only the two bracketing columns vote: 0.631 on column 11 (value 1531.5) and 0.369 on column 12 (value 1534), giving 1532.422275553417.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 9, 'A pick lands outside the frame. What does the tie table show?', '["An exception that aborts the whole tie table when any landing leaves the frame.", "A row with a null surface and null residual, reported rather than omitted.", "No row at all for that pick.", "A residual computed against the nearest live node along the frame''s edge."]'::jsonb, 1, 'Null samples produce null-residual ROWS by design: a well walking off the mapped area must be visible and countable in QC, not silently shorter.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 10, 'Which surfaces do the ties sample: raw resampled or clamped?', '["Clamped: the tie is against the model as built, including the clamp''s edits.", "Raw: the clamp is cosmetic bookkeeping and is deliberately excluded from quality control.", "Both are sampled, and the table reports whichever residual is larger.", "Raw for TopA and TopB, clamped for BaseB only."]'::jsonb, 0, 'There is one defensible order: clamp the stack, sample the clamped surface, subtract. Where the clamp moved BaseB, the tie measures disagreement with the CLAMPED BaseB, which becomes the heart of the next module.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 11, 'Why is ''correct the residual for the clamp afterwards'' not a valid shortcut?', '["The clamp''s node list is not stored anywhere the sampler could read it.", "It double-counts the kelly bushing height.", "It is a valid shortcut, and the engine offers it as a documented sampling option.", "Sampling does not commute with clamping, so the result is a different number."]'::jsonb, 3, 'The clamp couples the stack node by node before sampling blends values; applying it after sampling produces a different number. The engine offers no such option, deliberately.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 12, 'All twelve golden tie rows are live. What would change that?', '["A well with more than three picks.", "A surface whose clamp count is nonzero anywhere within the landing''s neighbourhood.", "A landing over any dead corner node, or outside the frame.", "A pick whose residual exceeds 50 m."]'::jsonb, 2, 'Null rows come from sampling geography, not from residual size or clamp counts. The golden landings all sit over fully live neighbourhoods.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 13, 'What certifies that the vertical wells'' residuals contain no rounding at all?', '["They are read from the fixture rather than computed.", "Every input is an integer or half-integer.", "The 0.01 grading tolerance absorbs any float error.", "The engine computes them in extended precision."]'::jsonb, 1, 'The arithmetic never leaves exact numbers: 1595 - 25 - 1565 = 5. That is why the capstone can grade them tightly; a disagreement is a mistake, not precision.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 14, 'A trajectory bug moves W2''s TopA landing 20 m further east. Which parts of the tie row change?', '["The landed position, the sampled surface value and blend weights, and the residual.", "Only the residual changes; the surface read is fixed once per top when the table is built.", "Only the landed position; the residual itself is trajectory-independent.", "Nothing, because the pick''s MD did not change."]'::jsonb, 0, 'Trajectory error moves WHERE the surface is read, which nodes vote and by how much, and the pick''s TVDSS. All three feed the residual.'),
  ('earthmodel', 'intermediate', 'module', 'm03-landing-the-tops', 15, 'What position does the landing machinery return for a pick at a survey station''s exact MD?', '["The midpoint of the two segments adjacent to that survey station.", "A blend of the station with the implied start at the surface, weighted by MD.", "Null: stations cannot carry picks.", "The station''s stored position, since the interpolation fraction is zero."]'::jsonb, 3, 'A pick at MD 1500 lands on station 1500 exactly; interpolation with fraction 0 leaves the station untouched. The degenerate case falls out of the same formula.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 1, 'Define the tie residual and its sign convention.', '["Pick TVDSS minus surface depth; positive means the pick sits deeper.", "Surface depth minus pick TVDSS; positive means the surface is too deep.", "The absolute gap between the pick and its surface, always kept positive.", "Pick MD minus surface depth, in metres of hole."]'::jsonb, 0, 'r = TVDSS_pick - z_surface, both positive down. The convention is arbitrary; its consistency is not, and half the classic blunders are silently flipped signs.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 2, 'A residual of minus 2 m at W1 TopA is compatible with which explanations?', '["Only a surface error: the picks are ground truth and are never revisited in QC.", "Only a pick error: the surfaces are fitted to honour all of the wells.", "A kelly bushing recorded 2 m too high.", "A surface too deep, a pick too shallow, or benign grid-resolution texture."]'::jsonb, 3, 'The residual measures disagreement and cannot arbitrate its cause; choosing needs outside evidence. A KB error would shift all three of W1''s residuals equally, and they are -2, +2, +5.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 3, 'What is the mean residual of the twelve rows, and what does its sign say?', '["Zero, as least squares guarantees.", "-9.17 m: the three surfaces run systematically deep across the field.", "+9.173973058869365 m: rock systematically deeper than the surfaces claim.", "+15.467112760762916 m: the average magnitude of the twelve signed disagreements."]'::jsonb, 2, 'The mean is +9.17 while the mean ABSOLUTE residual is 15.47; a mean this far positive says the disagreements do not cancel. Nothing here was fitted, so no zero-sum property applies.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 4, 'Which column of the tie table shows the signature of a uniform surface bias?', '["None; the apparent column patterns are coincidence of small numbers.", "TopB: +2, +8.3, +7, +6, same sign and similar size at every well.", "BaseB: +5, +45, +37, +36, the column whose entries share one sign and size.", "TopA: -2, -35.76, +1, +0.5."]'::jsonb, 1, 'A column that moves together points at the SURFACE: TopB runs a few metres shallow across the field. BaseB''s column is structural, and TopA''s is quiet except at the deviated well.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 5, 'Why can trajectory error not explain W3''s and W4''s BaseB residuals of +37 and +36 m?', '["Both wells are vertical, so there is no trajectory to be wrong.", "Their surveys were corrected before the fixture shipped, so no deviation remains.", "BaseB residuals never involve the trajectory in any well, vertical or not.", "The residuals are within tolerance of zero."]'::jsonb, 0, 'Vertical wells land picks at the wellhead by exact arithmetic. Whatever produces 37 m disagreements at W3 and W4 lives in the model or the picks, and the ledger identity pins it on the model''s pinched zone B.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 6, 'State the zone ledger identity for a vertical well.', '["BaseB residual plus TopB residual equals the model''s zone B thickness.", "BaseB residual equals the clamp count divided by the node area.", "TopB residual minus TopA residual equals the well''s zone A interval.", "BaseB minus TopB residual equals well zone B minus model zone B."]'::jsonb, 3, 'Subtracting the two ties cancels the shared datum terms and leaves well zone minus model zone. For W3: 37 - 7 = 30 - 0, exactly. The zone A version needs the model''s zone A on the right side too.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 7, 'The model''s zone B at W3 and W4 is 0 m. Why?', '["Zone B was never mapped east of the fault.", "Bilinear sampling returned null for BaseB there.", "The clamp fixed BaseB onto TopB there.", "The wells'' BaseB picks were deleted by QC."]'::jsonb, 2, 'At both wellheads the clamped TopB and BaseB surfaces read the same value (1598 and 1596). That is the Associate tier''s 180 fixed nodes appearing in the tie table.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 8, 'What is the precise, falsifiable statement the ledger turns the eastern residuals into?', '["The frame''s 50 m cells are too coarse to resolve anything east of the fault.", "The model''s pinch-out is contradicted by 30 m of logged section at two wells.", "The eastern surfaces are uniformly 37 m too shallow everywhere east of the fault.", "W3 and W4 have wrong kelly bushing heights."]'::jsonb, 1, 'Where the model says zone B is absent, two independent vertical wells logged 30 m of it. Both cannot be right, and that sentence is what gets handed to the mapping team.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 9, 'W2''s BaseB residual is +45.03 m. What is the honest attribution?', '["Mostly the missing-zone signal, with deviation setting where it is measured.", "Pure trajectory: the deviation moved the bottom of the hole east.", "Pure pick error at 1760 m MD.", "An artefact of bilinear sampling at a landing that misses every node of the frame."]'::jsonb, 0, '45.03 - 8.32 = 36.71 matches the eastern wells'' missing-zone ledger, while deviation landed the measurement 296 m east and made the digits non-integer. The slogan ''deviation did it'' misdirects the fix toward the survey.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 10, 'Why is worst-by-absolute-value the right convention for ranking residuals?', '["Because absolute values are cheaper to compute than signed comparisons.", "Because signed maxima are undefined whenever a table mixes positive and negative rows.", "Because the capstone grades only magnitudes.", "Because a large negative disagreement is as alarming as a large positive one."]'::jsonb, 3, 'W2 TopA at -35.76 is the set''s second-worst problem; a signed maximum would rank it last. The capstone grades the signed values but ranks by magnitude.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 11, 'What would a 9 m downward shift of all three surfaces do to the table?', '["Leave the table unchanged, since residuals are invariant under vertical shifts.", "Fix the TopB bias exactly.", "Improve the BaseB column while making three of four TopA ties worse.", "Improve every row by about 9 m."]'::jsonb, 2, 'The mean of +9.17 conflates three mechanisms. TopA''s column (-2, -35.76, +1, +0.5) mostly worsens under a downward shift; averages across mechanisms are how tie tables get misused.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 12, 'A whole well''s residuals share one unexplained offset. What is the classic suspect?', '["Spline overshoot in the surfaces near that particular wellhead.", "A kelly bushing error, which shifts every tie in that well equally.", "A pinched zone at that well.", "A swapped surface index for one top, rearranging the residual pattern across tops."]'::jsonb, 1, 'KB enters every TVDSS in the well identically. A swapped surface index would rearrange the PATTERN across tops instead, and zone effects hit specific columns.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 13, 'Is the tie table an error bar on the surfaces?', '["No: it measures disagreement at twelve points, not uncertainty everywhere.", "Yes: each residual is one standard deviation of the surface''s local uncertainty.", "Yes, once each residual is divided by the square root of twelve.", "No: it is an error bar on the picks instead."]'::jsonb, 0, 'Away from wells the surface could be better or worse; at wells the model can be reconciled exactly. Uncertainty machinery (jackknives, cross validation) lives in the mapping ladder, not here.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 14, 'Why not subtract each residual from its surface locally and declare the model tied?', '["Because residuals cannot be interpolated between wells.", "Because the engine forbids editing surfaces.", "Because the residuals would then all become positive.", "A local warp either fights the clamp or breaks stack validity."]'::jsonb, 3, 'Blind local correction bakes a contested pinch-out into the surfaces, and honouring 30 m of zone B where the clamp erases it either re-clamps away the fix or produces BaseB above TopB. Reconciliation is a mapping decision.'),
  ('earthmodel', 'intermediate', 'module', 'm04-the-tie-table', 15, 'Which pair of residuals shows one well containing both the largest and one of the smallest disagreements?', '["W2: TopB at +8.3 and BaseB at +45.", "W3: TopA at +1 and TopB at +7.", "W4: TopA at +0.5 and BaseB at +36.", "W1: TopA at -2 against BaseB at +5."]'::jsonb, 2, 'W4''s half-metre TopA tie is the table''s best and its BaseB carries the pinch-out''s full 30 m plus the TopB bias. One well, both extremes, and the ledger explains the coexistence.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 1, 'What does the vertical assumption cost on the three genuinely vertical wells?', '["A uniform 2 m depth shift inherited from each well''s bushing.", "Their control points move to the zone midpoints along the assumed hole.", "Their residuals lose their signs.", "Nothing: the assumption is free exactly where it is true."]'::jsonb, 3, 'W1, W3 and W4 are plumb lines, so replacing the survey with a vertical hole changes nothing. That is why the assumption survives in quick-look workflows.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 2, 'Under the vertical assumption, W2''s TopA residual reads +26 m. What is dangerous about that number?', '["It is null, so the row vanishes from the table.", "It rounds to the true value at the grading tolerance.", "It looks plausible while the true residual is -35.76.", "It exceeds the model''s total relief, so it would be dismissed."]'::jsonb, 2, '112 and 157 m announce themselves as absurd; +26 does not. A modeller acting on it would pull the surface DOWN where the well says the formation is 35.76 m SHALLOWER: a correction applied backwards.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 3, 'What are the vertical-assumption residuals at W2''s three picks?', '["Zero at all three picks, by construction of the assumption.", "+26, +112.00000000000023 and +157.00000000000023.", "-35.76, +8.32 and +45.03.", "+53.34, +88.48 and +106.06, the three depth errors."]'::jsonb, 1, 'TopA, TopB, BaseB under the assumption. The set beginning -35.76 is the TRUE residual triple, and the set beginning +53.34 is the pick-by-pick TVDSS overbooking, one channel of the error rather than the residual.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 4, 'Name the two error channels the vertical assumption opens.', '["Depth overbooking and location error.", "Bushing subtraction and azimuth drift.", "Blend-weight error and clamp coupling.", "Pick miscorrelation and survey sparsity."]'::jsonb, 0, 'Channel one misbooks sideways travel as depth; channel two reads the surface up to 296 m from the true landing. They are independent quantities with independent bounds.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 5, 'What determines the size of the location-error channel?', '["The measured depth of the deepest pick along the surveyed hole.", "The kelly bushing height.", "The dogleg of the build segment alone, since only the turn displaces the hole.", "The surface''s own relief between the wellhead and the true landing."]'::jsonb, 3, 'Reading the surface in the wrong place costs whatever the surface CHANGES across the displacement: zero on a flat surface, dominant on a steep one. The reach sets where, the relief sets how much.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 6, 'On this model, do the two channels cancel anywhere along W2?', '["Yes, wherever the surface is flat.", "They cancel exactly at the zone A midpoint, where the weights balance.", "No: the surfaces deepen eastward, so at every pick the channels compound.", "Yes, at TopB, where the modest swing shows the two channels offsetting each other."]'::jsonb, 2, 'The swing is the overbooking PLUS the surface''s rise from head to landing, and both are positive at all three picks: 61.76, 103.68 and 111.97 m. Cancellation would need the surface to shallow eastward by matching amounts.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 7, 'Give the bound on the depth channel for a 2000 m hole with up to 5 degrees of unnoticed deviation.', '["About 100 m, one cell of the model frame.", "About 7.6 m, from MD times one minus the cosine of the maximum inclination.", "About 174 m, from the measured depth times the sine of the maximum inclination there.", "Exactly zero, since 5 degrees is below the dogleg threshold."]'::jsonb, 1, '2000 (1 - cos 5) = 7.6 m. The 174 m figure is the LATERAL REACH bound, which feeds the other channel through the surface gradient.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 8, 'Why does a 3 degree survey doubt NOT threaten the eastern BaseB story?', '["Both channel bounds at W3 come to a few metres, far below the 36 and 37 m residuals.", "Because W3 and W4 were both resurveyed with gyros after the fixture shipped.", "Because BaseB residuals are immune to trajectory error.", "Because the vertical assumption remains exact for every hole inclined under 10 degrees."]'::jsonb, 0, 'At 1655 m of hole, 3 degrees bounds the depth channel at 2.3 m and the location channel at about a metre for local gradients. 36 m residuals cannot be manufactured by hidden deviation of that size.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 9, 'What happens to W2''s zone A control point under the vertical assumption?', '["It keeps its location but its weight drops from 120 to the 84.85 m of true rock.", "It moves to the zone''s TVD midpoint.", "It is dropped from the control set entirely, along with its weight.", "It snaps back to the wellhead at (1400, 2200); the weight stays 120."]'::jsonb, 3, 'The location is trajectory-derived and collapses to the wellhead; the weight is MD length, measured along the hole regardless of assumed shape. Location and weight fail independently.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 10, 'Why will the 211 m control point migration matter enormously one tier up?', '["Because the capstone directly grades the migration distance in metres.", "It will not; population uses wellheads.", "The fault at x 1575 runs between wellhead and point: their blocks differ.", "Because 211 m exceeds the variogram range assumed by the Expert tier''s kriging."]'::jsonb, 2, 'Population follows the control point. West of 1575 is one block, east the other, and W2''s data stands east while its rig stands west. The Expert tier''s block statistics pivot on exactly this.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 11, 'W2''s zone A is 120 m of hole but 84.8528137423857 m of vertical rock. What sets the ratio?', '["The clamp count on the BaseB surface.", "The cosine of the hold inclination.", "The ratio factor of the build, 1.0548.", "The bilinear blend weights at the midpoint."]'::jsonb, 1, 'In the hold, each metre of hole crosses cos 45 = 0.7071 m of rock; 120 times that is 84.85 = 60 sqrt 2. The build''s RF governs the arc segment, not the zone transit.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 12, 'What does MD weighting do to a deviated well''s vote in zone statistics?', '["Overweights it by 1 over cos of inclination relative to rock actually crossed.", "Underweights it, because the sideways part of the hole is discarded from the interval.", "Leaves it identical to thickness weighting.", "Sets it to zero when inclination exceeds 45 degrees."]'::jsonb, 0, 'MD length counts the sideways journey; thickness does not. At 45 degrees the factor is sqrt 2, about 41 percent extra weight for the same rock.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 13, 'Recomputing the four-well zone A weighted mean with W2''s weight cut to its TVD thickness moves it from 0.2903935560727246 to what?', '["0.28235504109413956, the arithmetic mean of the four wells.", "0.28631191845445614, the block 0 value.", "It does not move at all: the weights cancel inside any weighted mean.", "0.2898648855680765, a shift of about 0.0005."]'::jsonb, 3, 'The shift is half a unit in the third decimal, small because W2''s value sits mid-pack. The convention matters most when the heavy well is also the outlier.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 14, 'When does the choice between MD and thickness weighting matter MOST?', '["When the zone is thin everywhere and the wells are closely spaced.", "When the weights are all equal.", "When the heavily weighted well is also an outlier in value.", "When every well in the zone is vertical and the intervals are identical."]'::jsonb, 2, 'A convention shifts a mean in proportion to the reweighted well''s deviation from it. W2 sits near the middle here, so the golden model pays little; a deviated AND anomalous well is where the fight is worth having.'),
  ('earthmodel', 'intermediate', 'module', 'm05-the-cost-of-assuming-vertical', 15, 'Which check distinguishes ''bad trajectory'' from ''questionable weight convention'' for a control point?', '["Neither is checkable without redrilling the well and relogging the zone.", "Location wrongness is trajectory; weight wrongness is the MD convention.", "Both failure modes show up identically as a moved location on the map.", "Both show up as a changed weight."]'::jsonb, 1, 'The vertical assumption moved W2''s point 211 m but left its weight at 120; the MD-versus-thickness question biases the weight but not the location. A full audit visits both, independently.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 1, 'Why must the clamp run BEFORE any tie is sampled?', '["Sampling is undefined on unclamped grids.", "The clamp computes the kelly bushing corrections the ties depend on.", "The tie is against the model as built, and the clamp couples the stack.", "The clamp deletes wells that disagree with the surfaces beyond a tolerance."]'::jsonb, 2, 'One defensible order: clamp, sample, subtract. Editing any surface means re-clamping and re-sampling ALL tops, because the clamp couples them.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 2, 'What is the blast radius of editing one pick''s MD?', '["Nothing changes until the well''s survey is re-run from scratch.", "One tie row plus that zone''s control point and weight.", "Every row of that well.", "The whole table changes, through the clamp''s coupling of the stack."]'::jsonb, 1, 'A pick edit relands one pick and redefines one zone interval. The trajectory, other wells and other tops are untouched, which is what makes iterative reconciliation tractable.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 3, 'What is the blast radius of editing a SURVEY?', '["That well''s trajectory, all its landings and rows, and its control points.", "Only the deepest pick''s row, where the trajectory error is largest.", "All of the wells'' rows, since the four trajectories share their survey stations.", "The zone weights only."]'::jsonb, 0, 'The trajectory feeds every landing in the well and every zone midpoint. Other wells'' trajectories are independent; weights change only if picks change.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 4, 'Which QC checks certify the sampling and differencing plumbing jointly?', '["The mean residual being positive.", "The worst residual exceeding 40 m, as the fixture''s oracle expects.", "The panel rendering each of the four wells'' sections without any console errors.", "The zone ledger identities holding exactly at the vertical wells."]'::jsonb, 3, 'The ledger cross-checks four numbers per well computed through different code paths; holding at machine precision on W1, W3 and W4 certifies the plumbing. Summary statistics certify nothing structural.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 5, 'Name a cheap tripwire on trajectories from this module''s kit.', '["Every pick must land exactly on a grid node of the model frame.", "TVDSS must equal MD everywhere.", "Lateral reach must never exceed measured depth.", "Residuals must all be under 10 m before the table is published."]'::jsonb, 2, 'Reach beating hole length means broken trigonometry. The others are either false in general (nodes, TVDSS on deviated holes) or geology rather than machinery (residual size).'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 6, 'A draft of the panel modelled the assumed-vertical hole with an EMPTY survey. What happened, and which checks caught it?', '["The build''s ratio factor overflowed.", "Every pick clamped to MD 0; two independent checks fired.", "Nothing: an empty survey list is a perfectly valid vertical hole.", "Only W2 was affected, and no check fired because verticals are exempt."]'::jsonb, 1, 'minCurvature with no stations yields only the implied start, and positionAtMd clamps everything to it. Two independent alarms caught one bug; the fix was one deep vertical station.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 7, 'What does machinery QC deliberately NOT validate?', '["The inputs themselves: a consistently wrong KB passes every check.", "The sign convention of residuals across the twelve rows of the table.", "The bilinear blend weights.", "The order of the workflow''s steps from trajectories to the table."]'::jsonb, 0, 'Machinery checks bound what the numbers MEAN, not whether the world agrees with the inputs. The defence against input error is redundancy across wells, which is why the eastern story needed two wells.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 8, 'Which capstone field is a pipeline integrity check disguised as a lookup?', '["W1''s BaseB residual, whose exact 5 certifies every code path at once.", "W3''s TopA residual.", "The zone A control point weight, which sums every module''s arithmetic.", "The largest absolute residual, which needs the whole chain right."]'::jsonb, 3, 'Finding the worst row means computing all twelve correctly and comparing magnitudes. The vertical-well fields certify datums; the worst-residual field certifies the whole chain.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 9, 'Your pipeline reports W3 BaseB as the worst residual. What does that usually diagnose?', '["W3''s kelly bushing is wrong by the size of the discrepancy.", "Nothing: W3 BaseB at +37 really is the correct worst residual for the set.", "W2''s trajectory was never built, so its rows lost their magnitudes.", "The clamp was applied twice."]'::jsonb, 2, 'W2 BaseB at 45.03 beats W3''s 37 only when the deviated chain is computed. A vertical-assumption pipeline gives W2 BaseB +157, which would win differently; losing W2''s rows entirely leaves 37 on top.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 10, 'The capstone asks for W2''s control point x. A candidate answers 1653.2983248107264. What did they do?', '["Averaged the TopA and TopB landings, which the straight hold makes harmless.", "Reused the TopB landing instead of the zone midpoint''s.", "Assumed the well vertical and used the wellhead''s easting.", "Used the BaseB landing."]'::jsonb, 1, '1653.30 is the landing at MD 1700 (TopB). The midpoint of 1580 and 1700 is MD 1640, landing at 1610.87. The vertical assumption would give 1400, and the BaseB landing 1695.72. The average of the TopA and TopB landings, 1610.87, happens to be CORRECT here because both lie in the straight hold; the candidate who computed 1653.30 did not average.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 11, 'Why does re-running the whole workflow beat patching one number?', '["A patched output with stale provenance testifies falsely.", "Because patches require a database migration for every number changed.", "Because the workflow takes days to run.", "It does not; patching single numbers is standard, audited practice."]'::jsonb, 0, 'The workflow is cheap and deterministic, and its QC identities only hold on a coherent run. This is the engine family''s recompute-not-patch doctrine applied to QC itself.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 12, 'Which single change can move a well''s DATA into a different fault block one tier up?', '["A pick rename.", "A surface re-grid, which moves every value the ties compare against.", "A change of the capstone''s grading tolerance on the affected field.", "A survey revision, which relocates zone control points."]'::jsonb, 3, 'Control point locations are trajectory products. Surface edits move ties, not points; renames break the top binding; tolerances grade answers. Only the survey moves where the data stands.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 13, 'The tie workflow ends with which deliverables for the tier above?', '["A corrected survey for W2, honouring the tie table''s residuals.", "Per-block volumes.", "The tie table''s findings plus zone control points with MD weights.", "Re-gridded surfaces honouring every one of the twelve picks exactly at its landing."]'::jsonb, 2, 'This tier diagnoses and hands over: findings to the surface owners, control points to property population. Re-gridding is mapping''s decision; per-block volume is Expert work.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 14, 'Where should the eastern BaseB contradiction be resolved?', '["In the survey database, by adding enough deviation to W3 to explain it.", "Where the surfaces are made: it is a mapping work order.", "In the tie engine, by suppressing residuals above a configurable threshold.", "In the capstone, by widening tolerances."]'::jsonb, 1, 'The tie table converts vague trouble into a falsifiable statement about the pinch-out. Suppression, tolerance games or inventing deviation would each hide the disagreement instead of resolving it.'),
  ('earthmodel', 'intermediate', 'module', 'm06-the-well-tie-workflow', 15, 'What makes the vertical wells the control group of the whole tier?', '["Machinery trust is earned on hand-checkable integers first.", "They carry the largest residuals.", "They are immune to pick errors, which only deviated holes can suffer.", "They alone are graded by the capstone''s residual fields."]'::jsonb, 0, 'When the machinery reproduces -2, +2, +5 and friends exactly, its answer on the deviated well deserves trust. They are not immune to pick errors, and W2''s fields are graded too.'),
  ('earthmodel', 'intermediate', 'final', null, 1, 'The tie table exists to answer which question?', '["How far is each surface from where the wells found the formations?", "Which of the four golden wells was drilled the most accurately on target?", "How thick is each zone at every grid node?", "Whether the model frame''s 50 m cell size is adequate for the field''s relief."]'::jsonb, 0, 'Ties compare surfaces to rock, pick by pick. They grade neither drilling nor the frame, and thickness maps are Associate work.'),
  ('earthmodel', 'intermediate', 'final', null, 2, 'Order the three depth quantities for a point deep in a DEVIATED hole, largest first.', '["TVDSS, then TVD, then MD.", "TVD, then MD, then TVDSS.", "They are equal until the first survey station.", "MD, then TVD, then TVDSS."]'::jsonb, 3, 'Sideways travel makes MD exceed TVD, and subtracting a positive KB makes TVDSS smallest. Above the first station the implied start keeps MD equal to TVD, but TVDSS still differs by KB.'),
  ('earthmodel', 'intermediate', 'final', null, 3, 'W4''s TopA pick: MD 1584, KB 28, surface at the wellhead 1555.5. Residual?', '["+28.5 m, obtained by skipping the bushing subtraction entirely.", "+6 m, W4''s TopB entry.", "+0.5 m, the smallest disagreement in the table.", "-0.5 m, the surface running half a metre shallow."]'::jsonb, 2, '1584 - 28 = 1556; 1556 - 1555.5 = +0.5. Skipping KB gives 28.5, and +6 belongs to a different top.'),
  ('earthmodel', 'intermediate', 'final', null, 4, 'Why is the implied vertical start of every trajectory a CONVENTION rather than a fact?', '["Because the fixture''s wells all start deviated at the surface.", "''Vertical above the first station'' is a documented assumption.", "Because rigs cannot drill vertically.", "Because MD zero is below the kelly bushing, where surveys cannot reach."]'::jsonb, 1, 'Data constrains attitude only AT stations. Assuming vertical above the first is reasonable and stated; a different tool could assume differently and land shallow picks elsewhere.'),
  ('earthmodel', 'intermediate', 'final', null, 5, 'Which numbers does the ratio factor multiply?', '["The averaged end-attitude vectors, scaled by half the MD interval.", "The kelly bushing height and the water depth at the well location.", "The residuals of the affected well.", "The bilinear blend weights of the four nodes surrounding the landing point."]'::jsonb, 0, 'RF corrects the chord-versus-arc difference in the minimum curvature increments. It never touches datums, residuals or sampling.'),
  ('earthmodel', 'intermediate', 'final', null, 6, 'A pick at MD 1350 in W2 would land slightly OFF the true arc. Why?', '["Because 1350 m lies below the last survey station of the well.", "Because the dogleg exceeds the straightness threshold, so the engine refuses.", "It would not: landings are exact everywhere.", "Linear-in-MD interpolation cuts the corner inside the curved build."]'::jsonb, 3, 'Linear-in-MD interpolation cuts the corner of an arc segment. The golden picks all sit in the hold, where the convention is exact, which is why the capstone''s digits are clean.'),
  ('earthmodel', 'intermediate', 'final', null, 7, 'What is W2''s easting at its BaseB pick, and how is it split between build and hold?', '["282.84 m east, all from the hold.", "212.13 m east, the answer the tangential method would produce.", "295.72 m east: 111.88 from the build, 183.85 from the hold.", "295.72 m east, split as 147.86 m from each of the two deviated segments."]'::jsonb, 2, 'The build contributes 111.87696857341697 m; 260 m of hold adds 260/sqrt 2 = 183.84776310850236. The 62 percent hold share shows most reach comes from holding angle, not turning.'),
  ('earthmodel', 'intermediate', 'final', null, 8, 'Two wells pick TopA at identical MD; one lands 63 m shallower. What single sentence explains it?', '["The engine mixed up the two wells while assembling the table.", "Depth is a property of trajectory and datum, not cable length.", "One pick is 63 m miscorrelated.", "The TopA surface itself carries 63 m of relief between the two well locations."]'::jsonb, 1, 'W2 versus W3: same 1580 m MD, different KB and shape. Landed depth is derived, and the fixture built the coincidence to make exactly this point.'),
  ('earthmodel', 'intermediate', 'final', null, 9, 'Which landing situations return a NULL surface sample?', '["Outside the frame, or over any dead corner node.", "Any landing that does not fall exactly on a node of the frame.", "Any landing inside the clamp''s 180-node pinch-out region of the model.", "Landings below 1600 m TVDSS."]'::jsonb, 0, 'Nulls are geographic: off the frame or a compromised neighbourhood. Non-node landings blend normally, and clamped nodes are live values, not dead ones.'),
  ('earthmodel', 'intermediate', 'final', null, 10, 'The tie table''s TopB column reads +2, +8.3, +7, +6. What fix does that pattern call for?', '["Re-surveying all four wells.", "Deleting the four TopB picks from the wells as miscorrelated.", "Turning the clamp off for the TopB surface only.", "A small field-wide TopB surface adjustment."]'::jsonb, 3, 'Same sign, similar size at every well is a surface bias signature. No per-well mechanism is needed, and the clamp is not implicated in a uniform few-metre offset.'),
  ('earthmodel', 'intermediate', 'final', null, 11, 'For W1, the ledger gives BaseB minus TopB residual equal to 3. What does the 3 measure?', '["The bilinear blend residue left behind at a non-node landing position.", "The TopA surface''s local dip across W1''s neighbourhood.", "The well''s 30 m of zone B against the model''s 27 m at W1.", "The bushing error at W1."]'::jsonb, 2, 'The ledger identity subtracts shared datum terms: well zone minus model zone. W1 sits where the model still carries 27 m of zone B, so its entry is small where W3''s and W4''s are 30.'),
  ('earthmodel', 'intermediate', 'final', null, 12, 'What distinguishes W2''s TopA residual from every other large residual in the table?', '["It is null.", "It is negative and trajectory-borne, with no pinch-out to blame.", "It is the largest disagreement in the table in absolute value.", "It is exactly the model''s missing zone B."]'::jsonb, 1, '-35.76 at a top that exists everywhere: no pinch-out to blame, pure geometry of a deviated landing. The BaseB monsters are zone stories; this one is the trajectory story.'),
  ('earthmodel', 'intermediate', 'final', null, 13, 'Under the vertical assumption, which W2 row would pass a casual review, and why is that the trap?', '["TopA at +26: plausible size, silently wrong sign.", "BaseB at +157: a number too absurd for anyone to act on.", "TopB at +112: obviously absurd.", "None: all three of the rows look broken at first sight."]'::jsonb, 0, 'The inflated rows announce themselves. The small wrong-signed one carries no alarm, and acting on it applies a correction backwards. Cheap-looking numbers with silent sign errors are the expensive ones.'),
  ('earthmodel', 'intermediate', 'final', null, 14, 'The swing between assumed-vertical and true residuals decomposes into which two terms?', '["The dogleg plus the ratio factor.", "The clamp count at the landing plus the zone thickness the well logged.", "The blend weights plus the node values.", "The pick''s depth overbooking plus the surface''s rise to the true landing."]'::jsonb, 3, 'Swing = depth channel + relief channel. At W2''s picks: 53.34 + 8.42, 88.48 + 15.20, 106.06 + 5.91, all compounding on this model because the surfaces deepen eastward.'),
  ('earthmodel', 'intermediate', 'final', null, 15, 'A 2500 m well is believed vertical within 10 degrees over surfaces with gradients to 5 m per 100 m. Can a 12 m deep-pick residual be an assumption artefact?', '["No: residual artefacts of the assumption cannot exceed 10 m on any surface.", "Yes, but only through the location channel over steep surfaces.", "Yes easily: the depth channel alone bounds at about 38 m, dwarfing 12 m.", "No: both channels bound below 5 m."]'::jsonb, 2, '2500 (1 - cos 10) = 38 m; reach 434 m times 0.05 adds up to 22 m more. A 12 m residual on such a well is uninterpretable until the trajectory is built; the depth channel dominates here.'),
  ('earthmodel', 'intermediate', 'final', null, 16, 'Why does the zone A control point of a vertical well sit at its wellhead?', '["It does not: it sits at the zone''s centre of mass.", "Any MD midpoint in a vertical hole lands at the head''s x and y.", "Because the engine only computes control points for deviated wells.", "Because zone A is always shallower than the first survey station."]'::jsonb, 1, 'Vertical holes have no lateral travel, so every MD lands under the rig. The convention is invisible until deviation makes it visible at W2.'),
  ('earthmodel', 'intermediate', 'final', null, 17, 'W2''s zone A and zone B control points stand 63.64 m apart horizontally. Where does that number come from?', '["The 90 m of MD between the midpoints, divided by root two.", "The 60 m zone B interval multiplied by the build''s ratio factor.", "The difference of the two zones'' weights.", "The frame''s 50 m cell size plus half the polygon offset."]'::jsonb, 0, 'Midpoints at MD 1640 and 1730 are both in the 45 degree hold: 90/sqrt 2 = 63.64 m of easting between them. Deeper zones migrate further east along the hold.'),
  ('earthmodel', 'intermediate', 'final', null, 18, 'What is the capstone''s TopA TVDSS for W2, and which two trajectory quantities combine to give it?', '["1550 m: the pick''s measured depth minus the kelly bushing height.", "1440.0948948471319 m: the station value itself.", "1526.6634373420557 m: the TVD before KB.", "1496.6634373420557 m: the build endpoint plus a fifth of the hold advance."]'::jsonb, 3, '1440.0948948471319 + 0.2 x 282.84271247461896. The 1550 is the vertical-assumption answer, 1440.09 the station, and 1526.66 the TVD without the bushing subtracted.'),
  ('earthmodel', 'intermediate', 'final', null, 19, 'Which combination certifies BOTH datum handling and curvature arithmetic?', '["The deviated well alone.", "The mean residual being positive across the twelve tie rows.", "Vertical-well integer ties PLUS deviated fields matching the oracle.", "The vertical wells alone, whose arithmetic exercises every code path."]'::jsonb, 2, 'Verticals have zero dogleg and cannot test curvature; a deviated-only fixture leaves datums untested beneath the trajectory''s complexity. The fixture needs both, and has both.'),
  ('earthmodel', 'intermediate', 'final', null, 20, 'A candidate reports the worst residual as 35.75883821136131. What did they most likely do?', '["Read W3''s BaseB row.", "Took a signed minimum''s magnitude.", "Confused metres with feet when reading the table.", "Used the vertical assumption for the deviated well."]'::jsonb, 1, '35.76 is W2 TopA''s magnitude, the runner-up 9.27 m behind W2 BaseB''s 45.03. The vertical assumption would produce 157, and W3''s BaseB is 37.'),
  ('earthmodel', 'intermediate', 'final', null, 21, 'Editing the BaseB source surface re-runs which tie rows?', '["All BaseB rows, plus any rows whose surfaces the re-clamp moved.", "Only W2''s BaseB row.", "No rows: surfaces are sampled once at import time and cached thereafter.", "All twelve rows of every well, always, whatever surface changed."]'::jsonb, 0, 'The clamp couples the stack, so a BaseB edit can move clamped TopB values too. Nothing is cached across edits; the workflow re-runs, cheaply.'),
  ('earthmodel', 'intermediate', 'final', null, 22, 'What did this course conclude about the sentence ''the worst residual is 45 m because deviation moves the bottom of the hole''?', '["False number: the worst residual is 37 m.", "True and complete: trajectory explains all of it.", "Meaningless without the survey''s azimuth.", "True number, incomplete mechanism."]'::jsonb, 3, 'The slogan cannot explain 37 and 36 at vertical wells. Deviation set WHERE the disagreement was measured and its non-integer digits; the SIZE is mostly the pinched zone.'),
  ('earthmodel', 'intermediate', 'final', null, 23, 'What single property makes the tie workflow''s numbers auditable months later?', '["The panel stores screenshots.", "The surveys are immutable once loaded, so nothing can drift afterwards.", "Every step is a pure function of recorded inputs: regenerate and diff.", "The residuals were rounded to integers before being stored."]'::jsonb, 2, 'Recompute-not-patch: given fixtures and engines, the twelve rows regenerate bit for bit. Versioned inputs plus deterministic pipeline equals an audit trail.'),
  ('earthmodel', 'intermediate', 'final', null, 24, 'The x coordinate 1610.8719179395334 appears in the capstone. Between which two landed picks does it lie, and why exactly halfway?', '["Halfway between the wellhead and the fault.", "Between TopA''s 1568.45 and TopB''s 1653.30.", "Between TopB''s and BaseB''s landings.", "It is the wellhead''s x plus the build increment."]'::jsonb, 1, 'MD 1640 is the midpoint of 1580 and 1700, and linear geometry in the hold maps MD midpoints to position midpoints. The build increment lands at 1511.88, not here.'),
  ('earthmodel', 'intermediate', 'final', null, 25, 'Which error leaves every W2 residual intact but corrupts the Expert tier anyway?', '["A zone interval typo that moves the MD midpoint.", "A swapped TopA and TopB surface binding for the whole well set.", "A dropped survey station in the middle of the build.", "A kelly bushing typo."]'::jsonb, 0, 'Zone intervals feed control points, not ties. The other three all disturb the tie table itself, which would be caught there.'),
  ('earthmodel', 'intermediate', 'final', null, 26, 'Why are residuals NOT comparable across columns without context?', '["Because each column uses a different sign convention.", "Because the columns have different units.", "They are directly comparable; ranking by size is complete.", "Similar magnitudes can be different species."]'::jsonb, 3, 'W2 TopA''s 35.76 and W3 BaseB''s 37 are numerically kin and mechanistically strangers. Magnitude ranks attention; the column patterns direct it. Units and conventions are uniform.'),
  ('earthmodel', 'intermediate', 'final', null, 27, 'What would W1''s tie rows look like if TVDSS were computed as MD PLUS KB?', '["The rows are unchanged: KB cancels in the subtraction.", "The rows become null.", "Every W1 residual grows by exactly 50 m.", "Only the BaseB row changes."]'::jsonb, 2, 'A sign flip on KB shifts every tie in the well by 2 KB = 50 m. The uniform per-well offset is the fingerprint that convicts a datum error.'),
  ('earthmodel', 'intermediate', 'final', null, 28, 'The engine skips a pick named TOP_A. What is the QC that notices?', '["The build''s dogleg exceeding 45 degrees during the trajectory build.", "Counting tie rows per well against picks per well.", "The clamp count changing.", "The residuals in that well''s rows all becoming negative."]'::jsonb, 1, 'Name-based binding skips silently per pick; the visible symptom is a shorter table. Row-count-versus-pick-count is the cheap audit that catches naming drift.'),
  ('earthmodel', 'intermediate', 'final', null, 29, 'Rank the channels for W2 BaseB under the vertical assumption: which contributed more, and how much total swing?', '["Overbooking 106.06 m against relief 5.91; swing 111.97 m.", "Relief 106.06 m against overbooking 5.91 m; total 111.97 m.", "Equal contributions of about 56 m from each channel.", "Total swing 45.03 m."]'::jsonb, 0, 'At 45 degrees the depth channel is huge; the BaseB surface''s rise over the 296 m displacement is modest. 45.03 is the TRUE residual, not the swing.'),
  ('earthmodel', 'intermediate', 'final', null, 30, 'What makes the eastern BaseB finding CREDIBLE against the alternative that both picks are miscorrelated?', '["Vertical wells cannot have wrong picks.", "The engine validates every pick against stratigraphic order before tying it.", "The finding is graded by the capstone, so it must be true.", "Two wells log the same 30 m, agreeing with W1''s zone where the model has it."]'::jsonb, 3, 'Coherence across independent wells beats a surface extrapolated into a data gap; that is an argument, not an output, and a Professional should know which they are making.'),
  ('earthmodel', 'intermediate', 'final', null, 31, 'What do the twelve rows'' mean (+9.17) and mean-absolute (15.47) values jointly indicate?', '["That the surfaces are correct on average.", "That exactly nine of the twelve rows carry positive residuals.", "Systematic one-directional disagreement, not symmetric noise.", "That the table contains a computational error somewhere."]'::jsonb, 2, 'Symmetric noise would put the mean near zero regardless of size. A mean more than half the mean-absolute says the disagreements share a direction, fitting the one-way zone story.'),
  ('earthmodel', 'intermediate', 'final', null, 32, 'Which QC would catch surfaces sampled at (y, x) instead of (x, y)?', '["Nothing: the frame is symmetric enough that the swap cancels.", "The vertical controls: W1''s swapped read leaves the frame and goes null.", "The ledger identity, which is blind to the coordinate order used in sampling.", "The mean residual''s sign."]'::jsonb, 1, 'W1''s swapped location leaves the frame entirely (y range stops at 2950 northward but starts at 2000, and 1100 is below it), producing null rows the controls immediately flag. The frame is 25 x 20, nowhere near symmetric.'),
  ('earthmodel', 'intermediate', 'final', null, 33, 'A report needs ''wells in the model'' versus ''wells constraining the ties''. On this fixture, which numbers?', '["Four wells, twelve tie rows, all live.", "Four wells, but only the vertical ones constrain ties.", "Four wells, eleven live rows.", "Three wells; W2 is excluded as deviated."]'::jsonb, 0, 'All twelve landings sample live nodes, so no well or top drops out. Deviation changes WHERE constraints act, never whether they count.'),
  ('earthmodel', 'intermediate', 'final', null, 34, 'Why does the capstone ask for THREE residuals from different wells rather than one?', '["To average out pick errors.", "Because a single residual would be too easy to memorise and share.", "To test each of the three framework surfaces exactly equally.", "They jointly certify the shortcut, KB handling, the deviated chain and sampling."]'::jsonb, 3, 'W1 BaseB, W2 TopB and W3 TopA cover distinct code paths; a wrong pipeline fails specific fields in diagnosable ways. That is exam design, not padding.'),
  ('earthmodel', 'intermediate', 'final', null, 35, 'What is the one-sentence job description of minimum curvature?', '["Minimise the residuals of the tie table across the well set.", "Interpolate logs between stations.", "Connect successive attitudes with the smoothest consistent arc.", "Find the shortest possible path between the wellhead and total depth."]'::jsonb, 2, 'It is a trajectory model honouring measured attitudes, nothing more. It knows nothing of ties or logs, and it does not optimise path length.'),
  ('earthmodel', 'intermediate', 'final', null, 36, 'Which fixture design choice separates arc error from interpolation error?', '["Zone B is logged over 30 m of measured depth in every one of the wells.", "All of W2''s picks lie in the hold, past the build.", "The wells share a single kelly bushing height above the datum.", "The frame''s cells are 50 m."]'::jsonb, 1, 'Picks inside the build would mix chord-cutting into landings. Placing them in the hold makes landings exact, so any landing error is a real bug, not a convention artefact.'),
  ('earthmodel', 'intermediate', 'final', null, 37, 'The panel''s ''worst residual in the well set'' tile stays fixed while you switch wells. Why is that the right behaviour?', '["The worst residual is a property of the set, kept in view for triage.", "It is cached for performance.", "It updates only on a page reload of the course environment.", "It shows the currently displayed well''s worst top, recomputed per view."]'::jsonb, 0, 'Triage needs the global maximum in view whatever you inspect; a per-well tile would hide the set-level ranking the capstone asks for.'),
  ('earthmodel', 'intermediate', 'final', null, 38, 'Which number would change if W2''s azimuth were 080 instead of 090, all else equal?', '["Only the ratio factor.", "Nothing: azimuth never affects ties, only the map-view plot of the path.", "The kelly bushing correction applied to that well''s depths.", "Its landings'' y values, and through them the samples and residuals."]'::jsonb, 3, 'A non-east azimuth moves the path north as well as east; the landings shift in y, the blend weights change, and the residuals follow. The build''s RF is azimuth-blind from a vertical start, which is a different fact.'),
  ('earthmodel', 'intermediate', 'final', null, 39, 'What does the zone A ledger (TopB minus TopA residuals) reveal on this model?', '["The zone A picks are miscorrelated.", "Nothing: the ledger identity holds only for the zone B pair.", "The model''s zone A runs a few metres thin at the vertical wells.", "Zone A is pinched to zero thickness in the east, exactly like zone B."]'::jsonb, 2, 'Wells log 35, 45, 46 m of zone A against model thicknesses of 31, 39, 40.5: a mild, uniform thinness, much duller than zone B''s contradiction, which is exactly the point of running both ledgers.'),
  ('earthmodel', 'intermediate', 'final', null, 40, 'A reviewer asks: ''is 8.3 m at W2 TopB acceptable?'' What is the calibrated answer?', '["It cannot be judged without first rebuilding the azimuth of the survey.", "Calibrated against 50 m cells and a 36 m zone: worth a look, tolerable.", "No: anything above 5 m fails the quality gate outright.", "Yes: only null rows are problems."]'::jsonb, 1, 'Magnitude calibration runs against the model''s own scales, and the column context (all TopB ties +2 to +8) marks it as the shared surface bias, not a W2 problem.'),
  ('earthmodel', 'intermediate', 'final', null, 41, 'Which two capstone fields are exact integers or halves, and why?', '["W1 BaseB (+5) and W3 TopA (+1).", "W2 TopB and the worst residual.", "The control point x and W2''s TVDSS.", "None: all six carry float tails."]'::jsonb, 0, 'The two vertical-well fields are exact by construction, graded at 0.01 because disagreement means error, not precision. The deviated fields carry the trajectory''s irrational factors.'),
  ('earthmodel', 'intermediate', 'final', null, 42, 'The tie table is complete and green. What does the workflow do LAST?', '["Deletes the trajectories to save space.", "Re-clamps the framework one final time for the record.", "Rounds the twelve residuals to whole metres for the report.", "Derives the zone control points with their MD weights."]'::jsonb, 3, 'Ties diagnose; control points feed forward. The clamp ran before sampling, trajectories remain the audit trail, and rounding graded values is how hand checks go wrong.');
